def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def year_from_days(days, year=1980, max_passes=10_000):
    passes = 0
    while days > 365:
        passes += 1
        if passes > max_passes:      # a guard the real player did not have
            return None, days
        if is_leap(year):
            if days > 366:
                days -= 366
                year += 1
            # day 366 of a leap year: nothing changes
        else:
            days -= 365
            year += 1
    return year, days

