class CreditFailed(Exception):
    pass

balance = {"you": 5000, "friend": 800}

def credit(who, amount, bank_up):
    if not bank_up:
        raise CreditFailed("receiving bank did not respond")
    balance[who] += amount

def pay(amount, bank_up=True):
    balance["you"] -= amount                 # step 1: debit
    try:
        credit("friend", amount, bank_up)     # step 2: credit
    except CreditFailed as problem:
        balance["you"] += amount              # undo step 1
        print("reversed:", problem)
    else:
        print("paid", amount)
    finally:
        print("SMS -> you:", balance["you"], "| friend:", balance["friend"])

pay(1200, bank_up=False)   # reversed, and both balances as they were
pay(1200)                  # paid: you 3800, friend 2000

