import datetime

# What a spreadsheet does on the way in: look at the characters, pick a kind.
def guess(cell):
    try:
        return int(cell)
    except ValueError:
        pass
    for form in ("%d-%b", "%b-%d"):
        try:
            return datetime.datetime.strptime(cell, form).date().isoformat()
        except ValueError:
            pass
    return cell

